draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-75, 100, 150);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2-100, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-80);
  ctx.lineTo(W/2, H/2-40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-60);
  ctx.lineTo(W/2-30, H/2-40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-60);
  ctx.lineTo(W/2+30, H/2-40);
  ctx.stroke();

  // applying wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Applying Wisdom', W/2, H/2+50 + 20 * Math.sin(t));

  // lesson life
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson for Life', W/2, H/2+100 + 20 * Math.cos(t));

  ctx.restore();
}
